// Server-side split of the flat catalogue (full-test 15/11 PUBLIC-04): what the client receives through the RSC payload.
// - The locale layout gives every page the public subset (`src/i18n/public-keys.json`, generated by
//   `scripts/public-messages.mjs` from the import graph of the public / auth / status / tracking routes).
// - The merchant app, the admin, the onboarding and the other non-public routes add the rest of the catalogue in their own
//   layout with `<FullMessages>` (merged into the public subset by `ExtendMessages`, so no key is sent twice).
// Server code (`serverT`, metadata, opengraph images) keeps reading the whole catalogue with `getMessages`.
import { getMessages, isAppLocale, type AppLocale } from '@djaber/shared';
import type { ReactNode } from 'react';
import PUBLIC_KEYS from '@/i18n/public-keys.json';
import { ExtendMessages } from './i18n';

type Flat = Record<string, string>;
const PUBLIC = new Set<string>(PUBLIC_KEYS);
const cache = new Map<string, Flat>();
const localeOf = (raw: string): AppLocale => (isAppLocale(raw) ? raw : 'fr');

const split = (raw: string, part: 'public' | 'rest'): Flat => {
  const locale = localeOf(raw);
  const id = `${part}:${locale}`;
  const hit = cache.get(id);
  if (hit) return hit;
  const out: Flat = {};
  for (const [k, v] of Object.entries(getMessages(locale))) if (PUBLIC.has(k) === (part === 'public')) out[k] = v;
  cache.set(id, out);
  return out;
};

/** The keys the public pages, the auth pages and the locale-level 404 / error pages can show. */
export const publicMessages = (locale: string): Flat => split(locale, 'public');
/** Every other key of the catalogue (merchant app, admin, onboarding…). */
export const restMessages = (locale: string): Flat => split(locale, 'rest');

/** Wraps a non-public route group: its client components read the whole catalogue. */
export function FullMessages({ locale, children }: { locale: string; children: ReactNode }) {
  return <ExtendMessages messages={restMessages(locale)}>{children}</ExtendMessages>;
}
